export const MIGRATION_SQL: Readonly<Record<string, string>> = {
  "0001_init.sql": "-- Grant Finder Studio — initial schema.\n--\n-- Two classes of table:\n--   TENANT-SCOPED  carry organisation_id and are protected by Row-Level Security.\n--   SHARED         reference data (funders, opportunities, licences) readable by\n--                  every tenant and writable only by the ingestion role.\n--\n-- Tenant isolation is enforced by Postgres, not by the application. Application\n-- level filtering fails open when a WHERE clause is forgotten; RLS fails closed.\n\n-- ---------------------------------------------------------------------------\n-- Enums. These exist so that whole classes of mistake become unrepresentable.\n-- ---------------------------------------------------------------------------\n\nCREATE TYPE jurisdiction AS ENUM (\n  'england', 'wales', 'scotland', 'northern_ireland', 'uk_wide'\n);\n\nCREATE TYPE legal_form AS ENUM (\n  'cic_limited_by_guarantee', 'cic_limited_by_shares', 'charity',\n  'charitable_incorporated_organisation', 'community_benefit_society',\n  'company_limited_by_guarantee', 'company_limited_by_shares',\n  'unincorporated_association', 'other'\n);\n\n-- How a funder treats the CIC legal form. 'not_stated' is deliberately a value\n-- rather than a null: silence is a finding, and the product acts on it.\nCREATE TYPE cic_treatment AS ENUM (\n  'explicitly_permitted', 'charity_only', 'asset_locked_only',\n  'limited_by_guarantee_only', 'no_share_capital_only',\n  'permitted_with_conditions', 'not_stated'\n);\n\nCREATE TYPE freshness AS ENUM (\n  'current', 'recently_verified', 'needs_verification', 'stale', 'closed', 'unknown'\n);\n\n-- Kept separate from the date itself so an estimate can never render as confirmed.\nCREATE TYPE deadline_type AS ENUM (\n  'confirmed', 'rolling', 'expected', 'estimated', 'unknown'\n);\n\nCREATE TYPE source_type AS ENUM (\n  'user', 'document', 'companies_house', '360giving', 'funder_published', 'ai_extraction'\n);\n\nCREATE TYPE confidence AS ENUM ('high', 'medium', 'low');\n\nCREATE TYPE membership_role AS ENUM ('owner', 'admin', 'editor', 'viewer');\n\nCREATE TYPE application_status AS ENUM (\n  'discovered', 'saved', 'eligibility', 'strategy', 'drafting', 'review',\n  'submitted', 'awarded', 'rejected', 'reporting', 'complete'\n);\n\nCREATE TYPE review_mode AS ENUM ('standard', 'red_team');\n\nCREATE TYPE cost_category AS ENUM (\n  'staff', 'freelancers', 'equipment', 'materials', 'venues', 'travel',\n  'training', 'marketing', 'evaluation', 'management', 'overheads', 'capital'\n);\n\n-- ---------------------------------------------------------------------------\n-- Shared reference data. Not tenant-scoped.\n-- ---------------------------------------------------------------------------\n\n-- Every ingested dataset records its licence. 360Giving publishers choose their\n-- own open licences and some are share-alike, which propagates to derived data.\n-- Licence therefore travels with the data rather than living in a wiki.\nCREATE TABLE source_datasets (\n  id              text PRIMARY KEY,\n  name            text NOT NULL,\n  publisher       text NOT NULL,\n  licence         text NOT NULL,\n  licence_url     text,\n  attribution     text NOT NULL,\n  terms_url       text,\n  permitted_uses  text,\n  retrieved_at    timestamptz NOT NULL,\n  created_at      timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE funders (\n  id              text PRIMARY KEY,\n  name            text NOT NULL,\n  website         text,\n  jurisdiction    jurisdiction,\n  -- Attributes the funder itself publishes, kept apart from anything derived.\n  stated_priorities  text,\n  -- Attributes we computed from awarded-grants data. Never presented as official.\n  derived_summary    text,\n  source_dataset_id  text REFERENCES source_datasets(id),\n  created_at      timestamptz NOT NULL DEFAULT now()\n);\n\n-- Awarded grants, from 360Giving. Evidence of what a funder actually funds.\nCREATE TABLE funder_awards (\n  id                text PRIMARY KEY,\n  funder_id         text NOT NULL REFERENCES funders(id) ON DELETE CASCADE,\n  recipient_name    text,\n  amount_gbp        numeric(12,2),\n  awarded_on        date,\n  description       text,\n  jurisdiction      jurisdiction,\n  region            text,\n  source_dataset_id text NOT NULL REFERENCES source_datasets(id),\n  created_at        timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE INDEX funder_awards_funder_idx ON funder_awards (funder_id);\nCREATE INDEX funder_awards_awarded_on_idx ON funder_awards (awarded_on DESC);\n\nCREATE TABLE opportunities (\n  id                text PRIMARY KEY,\n  funder_id         text NOT NULL REFERENCES funders(id) ON DELETE CASCADE,\n  title             text NOT NULL,\n  summary           text,\n  min_amount_gbp    numeric(12,2),\n  max_amount_gbp    numeric(12,2),\n  jurisdiction      jurisdiction,\n  deadline          date,\n  deadline_kind     deadline_type NOT NULL DEFAULT 'unknown',\n  freshness_state   freshness NOT NULL DEFAULT 'unknown',\n  source_url        text,\n  source_dataset_id text REFERENCES source_datasets(id),\n  retrieved_at      timestamptz NOT NULL,\n  verified_at       timestamptz,\n  created_at        timestamptz NOT NULL DEFAULT now(),\n  -- A confirmed deadline must actually have a date.\n  CONSTRAINT confirmed_deadline_has_date\n    CHECK (deadline_kind <> 'confirmed' OR deadline IS NOT NULL)\n);\n\nCREATE INDEX opportunities_funder_idx ON opportunities (funder_id);\nCREATE INDEX opportunities_deadline_idx ON opportunities (deadline);\nCREATE INDEX opportunities_freshness_idx ON opportunities (freshness_state);\n\n-- Machine-evaluable criteria. Proposed by extraction, verified by a human, and\n-- evaluated by the deterministic engine in src/domain/eligibility.\nCREATE TABLE eligibility_criteria (\n  id              text PRIMARY KEY,\n  opportunity_id  text NOT NULL REFERENCES opportunities(id) ON DELETE CASCADE,\n  kind            text NOT NULL,\n  label           text NOT NULL,\n  -- Structured parameters for the criterion, shaped by `kind`.\n  params          jsonb NOT NULL,\n  cic_handling    cic_treatment,\n  verified_by     text,\n  verified_at     timestamptz,\n  created_at      timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE INDEX eligibility_criteria_opportunity_idx\n  ON eligibility_criteria (opportunity_id);\n\n-- ---------------------------------------------------------------------------\n-- Tenancy.\n-- ---------------------------------------------------------------------------\n\nCREATE TABLE users (\n  id          text PRIMARY KEY,\n  email       text NOT NULL UNIQUE,\n  name        text,\n  created_at  timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE organisations (\n  id          text PRIMARY KEY,\n  name        text NOT NULL,\n  created_at  timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE memberships (\n  id               text PRIMARY KEY,\n  organisation_id  text NOT NULL REFERENCES organisations(id) ON DELETE CASCADE,\n  user_id          text NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  role             membership_role NOT NULL,\n  created_at       timestamptz NOT NULL DEFAULT now(),\n  UNIQUE (organisation_id, user_id)\n);\n\n-- ---------------------------------------------------------------------------\n-- Tenant-scoped organisation knowledge.\n-- ---------------------------------------------------------------------------\n\nCREATE TABLE organisation_profiles (\n  id                  text PRIMARY KEY,\n  organisation_id     text NOT NULL REFERENCES organisations(id) ON DELETE CASCADE,\n  legal_name          text,\n  company_number      text,\n  form                legal_form,\n  incorporation_date  date,\n  jurisdiction        jurisdiction,\n  region              text,\n  annual_turnover_gbp numeric(12,2),\n  mission             text,\n  updated_at          timestamptz NOT NULL DEFAULT now(),\n  UNIQUE (organisation_id)\n);\n\nCREATE TABLE projects (\n  id                  text PRIMARY KEY,\n  organisation_id     text NOT NULL REFERENCES organisations(id) ON DELETE CASCADE,\n  name                text NOT NULL,\n  description         text,\n  beneficiary_groups  text[] NOT NULL DEFAULT '{}',\n  region              text,\n  amount_sought_gbp   numeric(12,2),\n  duration_months     integer,\n  created_at          timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE INDEX projects_org_idx ON projects (organisation_id);\n\n-- Facts are append-only. A correction supersedes rather than overwrites, so\n-- the record of what the organisation believed, and when, survives.\nCREATE TABLE facts (\n  id               text PRIMARY KEY,\n  organisation_id  text NOT NULL REFERENCES organisations(id) ON DELETE CASCADE,\n  claim            text NOT NULL,\n  value            text NOT NULL,\n  source           source_type NOT NULL,\n  source_ref       text,\n  source_span      text,\n  retrieved_at     timestamptz NOT NULL,\n  confidence_level confidence NOT NULL DEFAULT 'medium',\n  confirmed_by     text REFERENCES users(id),\n  confirmed_at     timestamptz,\n  superseded_by    text REFERENCES facts(id),\n  created_at       timestamptz NOT NULL DEFAULT now(),\n  -- A confirmation must record both who and when.\n  CONSTRAINT confirmation_is_complete\n    CHECK ((confirmed_by IS NULL) = (confirmed_at IS NULL))\n);\n\nCREATE INDEX facts_org_claim_idx ON facts (organisation_id, claim);\nCREATE INDEX facts_current_idx ON facts (organisation_id) WHERE superseded_by IS NULL;\n\nCREATE TABLE evidence (\n  id               text PRIMARY KEY,\n  organisation_id  text NOT NULL REFERENCES organisations(id) ON DELETE CASCADE,\n  claim            text NOT NULL,\n  source_name      text NOT NULL,\n  source_url       text,\n  published_on     date,\n  jurisdiction     jurisdiction,\n  region           text,\n  population       text,\n  review_by        date,\n  created_at       timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE INDEX evidence_org_idx ON evidence (organisation_id);\n\nCREATE TABLE documents (\n  id               text PRIMARY KEY,\n  organisation_id  text NOT NULL REFERENCES organisations(id) ON DELETE CASCADE,\n  filename         text NOT NULL,\n  mime_type        text NOT NULL,\n  byte_size        bigint NOT NULL,\n  storage_key      text NOT NULL,\n  classified_as    text,\n  uploaded_by      text REFERENCES users(id),\n  created_at       timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE INDEX documents_org_idx ON documents (organisation_id);\n\nCREATE TABLE document_chunks (\n  id               text PRIMARY KEY,\n  organisation_id  text NOT NULL REFERENCES organisations(id) ON DELETE CASCADE,\n  document_id      text NOT NULL REFERENCES documents(id) ON DELETE CASCADE,\n  chunk_index      integer NOT NULL,\n  content          text NOT NULL,\n  page_number      integer,\n  created_at       timestamptz NOT NULL DEFAULT now(),\n  UNIQUE (document_id, chunk_index)\n);\n\nCREATE INDEX document_chunks_org_idx ON document_chunks (organisation_id);\n\n-- ---------------------------------------------------------------------------\n-- Applications.\n-- ---------------------------------------------------------------------------\n\nCREATE TABLE applications (\n  id               text PRIMARY KEY,\n  organisation_id  text NOT NULL REFERENCES organisations(id) ON DELETE CASCADE,\n  opportunity_id   text REFERENCES opportunities(id),\n  project_id       text REFERENCES projects(id),\n  status           application_status NOT NULL DEFAULT 'saved',\n  amount_requested_gbp numeric(12,2),\n  submitted_at     timestamptz,\n  outcome_note     text,\n  amount_awarded_gbp   numeric(12,2),\n  created_at       timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE INDEX applications_org_idx ON applications (organisation_id);\nCREATE INDEX applications_status_idx ON applications (organisation_id, status);\n\nCREATE TABLE application_questions (\n  id               text PRIMARY KEY,\n  organisation_id  text NOT NULL REFERENCES organisations(id) ON DELETE CASCADE,\n  application_id   text NOT NULL REFERENCES applications(id) ON DELETE CASCADE,\n  position         integer NOT NULL,\n  question         text NOT NULL,\n  word_limit       integer,\n  guidance         text,\n  assesses         text,\n  UNIQUE (application_id, position)\n);\n\nCREATE INDEX application_questions_org_idx ON application_questions (organisation_id);\n\nCREATE TABLE answers (\n  id               text PRIMARY KEY,\n  organisation_id  text NOT NULL REFERENCES organisations(id) ON DELETE CASCADE,\n  question_id      text NOT NULL REFERENCES application_questions(id) ON DELETE CASCADE,\n  content          text NOT NULL DEFAULT '',\n  word_count       integer NOT NULL DEFAULT 0,\n  updated_at       timestamptz NOT NULL DEFAULT now(),\n  UNIQUE (question_id)\n);\n\nCREATE INDEX answers_org_idx ON answers (organisation_id);\n\nCREATE TABLE answer_versions (\n  id               text PRIMARY KEY,\n  organisation_id  text NOT NULL REFERENCES organisations(id) ON DELETE CASCADE,\n  answer_id        text NOT NULL REFERENCES answers(id) ON DELETE CASCADE,\n  content          text NOT NULL,\n  created_by       text REFERENCES users(id),\n  ai_generation_id text,\n  created_at       timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE INDEX answer_versions_org_idx ON answer_versions (organisation_id);\n\n-- Sentence-level provenance: which fact backs which claim in a drafted answer.\nCREATE TABLE answer_fact_refs (\n  id               text PRIMARY KEY,\n  organisation_id  text NOT NULL REFERENCES organisations(id) ON DELETE CASCADE,\n  answer_id        text NOT NULL REFERENCES answers(id) ON DELETE CASCADE,\n  fact_id          text REFERENCES facts(id),\n  claim_text       text NOT NULL,\n  -- True when the sentence asserts something with no confirmed fact behind it.\n  is_unsupported   boolean NOT NULL DEFAULT false,\n  created_at       timestamptz NOT NULL DEFAULT now(),\n  -- An unsupported claim has no fact; a supported one must have one.\n  CONSTRAINT unsupported_has_no_fact\n    CHECK ((fact_id IS NULL) = is_unsupported)\n);\n\nCREATE INDEX answer_fact_refs_org_idx ON answer_fact_refs (organisation_id);\n\nCREATE TABLE reviews (\n  id               text PRIMARY KEY,\n  organisation_id  text NOT NULL REFERENCES organisations(id) ON DELETE CASCADE,\n  application_id   text NOT NULL REFERENCES applications(id) ON DELETE CASCADE,\n  mode             review_mode NOT NULL,\n  findings         jsonb NOT NULL DEFAULT '[]',\n  readiness_percent integer,\n  created_at       timestamptz NOT NULL DEFAULT now(),\n  CONSTRAINT readiness_in_range\n    CHECK (readiness_percent IS NULL OR (readiness_percent BETWEEN 0 AND 100))\n);\n\nCREATE INDEX reviews_org_idx ON reviews (organisation_id);\n\nCREATE TABLE budgets (\n  id               text PRIMARY KEY,\n  organisation_id  text NOT NULL REFERENCES organisations(id) ON DELETE CASCADE,\n  application_id   text NOT NULL REFERENCES applications(id) ON DELETE CASCADE,\n  created_at       timestamptz NOT NULL DEFAULT now(),\n  UNIQUE (application_id)\n);\n\nCREATE INDEX budgets_org_idx ON budgets (organisation_id);\n\nCREATE TABLE budget_lines (\n  id               text PRIMARY KEY,\n  organisation_id  text NOT NULL REFERENCES organisations(id) ON DELETE CASCADE,\n  budget_id        text NOT NULL REFERENCES budgets(id) ON DELETE CASCADE,\n  category         cost_category NOT NULL,\n  description      text NOT NULL,\n  amount_gbp       numeric(12,2) NOT NULL,\n  CONSTRAINT amount_is_positive CHECK (amount_gbp > 0)\n);\n\nCREATE INDEX budget_lines_org_idx ON budget_lines (organisation_id);\n\nCREATE TABLE outcomes (\n  id               text PRIMARY KEY,\n  organisation_id  text NOT NULL REFERENCES organisations(id) ON DELETE CASCADE,\n  application_id   text NOT NULL REFERENCES applications(id) ON DELETE CASCADE,\n  activity         text NOT NULL,\n  output           text NOT NULL,\n  outcome          text NOT NULL,\n  indicator        text,\n  target           text,\n  created_at       timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE INDEX outcomes_org_idx ON outcomes (organisation_id);\n\n-- ---------------------------------------------------------------------------\n-- Operational.\n-- ---------------------------------------------------------------------------\n\nCREATE TABLE audit_logs (\n  id               text PRIMARY KEY,\n  organisation_id  text NOT NULL REFERENCES organisations(id) ON DELETE CASCADE,\n  user_id          text REFERENCES users(id),\n  action           text NOT NULL,\n  entity_type      text NOT NULL,\n  entity_id        text,\n  metadata         jsonb NOT NULL DEFAULT '{}',\n  created_at       timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE INDEX audit_logs_org_idx ON audit_logs (organisation_id, created_at DESC);\n\nCREATE TABLE ai_generations (\n  id               text PRIMARY KEY,\n  organisation_id  text NOT NULL REFERENCES organisations(id) ON DELETE CASCADE,\n  agent            text NOT NULL,\n  prompt_version   text NOT NULL,\n  model            text NOT NULL,\n  input_tokens     integer,\n  output_tokens    integer,\n  cost_pence       integer,\n  latency_ms       integer,\n  schema_valid     boolean NOT NULL,\n  created_at       timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE INDEX ai_generations_org_idx ON ai_generations (organisation_id, created_at DESC);\n\n-- ---------------------------------------------------------------------------\n-- Row-Level Security.\n--\n-- Every tenant-scoped table gets the same treatment:\n--   ENABLE + FORCE so even the table owner is subject to the policy\n--   USING      restricts which rows can be read, updated or deleted\n--   WITH CHECK stops a tenant writing a row attributed to another tenant\n--\n-- current_setting(..., true) returns NULL when unset, and `= NULL` is never\n-- true, so an unset tenant sees nothing. The system fails closed.\n-- ---------------------------------------------------------------------------\n\n-- Roles in Postgres are CLUSTER-scoped, not database-scoped. A plain\n-- CREATE ROLE therefore fails the second time this schema is applied anywhere\n-- in the same cluster — a staging database alongside production on the same\n-- Neon project is enough to break the first deploy.\n--\n-- The GRANT afterwards matters just as much. `SET LOCAL ROLE app_user` only\n-- works if the connecting role is a member of app_user (or a superuser, which\n-- a managed host will not give you). Postgres 16 grants the creator membership\n-- implicitly, but that is not something to depend on across hosts and\n-- versions, so it is stated explicitly and made safe to repeat.\nDO $$\nBEGIN\n  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'app_user') THEN\n    CREATE ROLE app_user NOLOGIN;\n  END IF;\n  EXECUTE format('GRANT app_user TO %I', current_user);\nEXCEPTION\n  -- Already a member. Harmless, and not worth failing a deploy over.\n  WHEN duplicate_object THEN NULL;\nEND $$;\n\nGRANT SELECT ON source_datasets, funders, funder_awards, opportunities,\n  eligibility_criteria TO app_user;\n\nDO $$\nDECLARE\n  t text;\n  tenant_tables text[] := ARRAY[\n    'organisation_profiles', 'projects', 'facts', 'evidence', 'documents',\n    'document_chunks', 'applications', 'application_questions', 'answers',\n    'answer_versions', 'answer_fact_refs', 'reviews', 'budgets',\n    'budget_lines', 'outcomes', 'audit_logs', 'ai_generations'\n  ];\nBEGIN\n  FOREACH t IN ARRAY tenant_tables LOOP\n    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);\n    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);\n    EXECUTE format(\n      'CREATE POLICY tenant_isolation ON %I\n         USING (organisation_id = current_setting(''app.organisation_id'', true))\n         WITH CHECK (organisation_id = current_setting(''app.organisation_id'', true))',\n      t\n    );\n    EXECUTE format('GRANT SELECT, INSERT, UPDATE, DELETE ON %I TO app_user', t);\n  END LOOP;\nEND $$;\n\n-- Organisations and memberships are visible only for the active tenant.\nALTER TABLE organisations ENABLE ROW LEVEL SECURITY;\nALTER TABLE organisations FORCE ROW LEVEL SECURITY;\nCREATE POLICY tenant_isolation ON organisations\n  USING (id = current_setting('app.organisation_id', true))\n  WITH CHECK (id = current_setting('app.organisation_id', true));\nGRANT SELECT, INSERT, UPDATE, DELETE ON organisations TO app_user;\n\nALTER TABLE memberships ENABLE ROW LEVEL SECURITY;\nALTER TABLE memberships FORCE ROW LEVEL SECURITY;\nCREATE POLICY tenant_isolation ON memberships\n  USING (organisation_id = current_setting('app.organisation_id', true))\n  WITH CHECK (organisation_id = current_setting('app.organisation_id', true));\nGRANT SELECT, INSERT, UPDATE, DELETE ON memberships TO app_user;\n\nGRANT SELECT ON users TO app_user;\n",
  "0002_credentials.sql": "-- Operator credentials.\n--\n-- These are the platform's own API keys, not a tenant's. CIC users never see\n-- or supply them: they sign up and use the product, and the platform pays for\n-- and manages its own provider access.\n--\n-- Deliberately NOT tenant-scoped and NOT covered by the RLS policies: no\n-- application role may read this table at all. Only the server-side settings\n-- code, running as the owner, touches it.\n\nCREATE TABLE app_credentials (\n  -- One row per provider, e.g. 'anthropic', 'companies_house'.\n  provider        text PRIMARY KEY,\n  -- AES-256-GCM ciphertext. Never plaintext, never returned to a browser.\n  ciphertext      text NOT NULL,\n  -- Display-only form such as 'sk-ant-…6789', safe to render.\n  masked          text NOT NULL,\n  -- Outcome of the last live check against the provider.\n  last_checked_at timestamptz,\n  last_check_ok   boolean,\n  last_check_note text,\n  updated_at      timestamptz NOT NULL DEFAULT now(),\n  updated_by      text REFERENCES users(id)\n);\n\n-- app_user is granted nothing here. The absence of a GRANT is the control.\nREVOKE ALL ON app_credentials FROM PUBLIC;\n",
  "0003_documents.sql": "-- Documents: store the extracted text, not the original bytes.\n--\n-- The original file is deliberately not retained. The extracted text is what\n-- source spans quote and what the confirmation screen shows, so keeping the\n-- bytes as well would mean a blob store, signed URLs, and a second copy of an\n-- organisation's private documents to secure and eventually lose. Storing\n-- less is the stronger position, and it is also the one that deploys.\n--\n-- So storage_key becomes nullable: there is no key when there is no blob.\n\nALTER TABLE documents ALTER COLUMN storage_key DROP NOT NULL;\n\n-- Where the ingest run got to. 'pending' exists so a row is never orphaned\n-- between upload and extraction; a document stuck there is visible rather\n-- than silently absent.\nCREATE TYPE extraction_state AS ENUM ('pending', 'extracted', 'failed');\n\nALTER TABLE documents\n  ADD COLUMN extraction_state extraction_state NOT NULL DEFAULT 'pending',\n  -- Shown to the user. Never a stack trace.\n  ADD COLUMN extraction_note text,\n  -- Null for formats with no fixed pages, such as .docx.\n  ADD COLUMN page_count integer,\n  ADD COLUMN character_count integer,\n  -- True when the document was longer than we were willing to read, so the\n  -- interface can say so instead of implying it read the whole thing.\n  ADD COLUMN truncated boolean NOT NULL DEFAULT false,\n  -- Text that addressed the model rather than describing the organisation.\n  -- Surfaced to the user: an injection attempt is a signal about the\n  -- document, not something to swallow quietly.\n  ADD COLUMN instruction_like_content text[] NOT NULL DEFAULT '{}',\n  ADD COLUMN extracted_at timestamptz;\n\nALTER TABLE documents\n  ADD CONSTRAINT extracted_documents_record_when\n    CHECK (extraction_state <> 'extracted' OR extracted_at IS NOT NULL),\n  ADD CONSTRAINT failed_documents_say_why\n    CHECK (extraction_state <> 'failed' OR extraction_note IS NOT NULL),\n  ADD CONSTRAINT page_count_is_positive\n    CHECK (page_count IS NULL OR page_count > 0);\n\nCREATE INDEX documents_state_idx ON documents (organisation_id, extraction_state);\n",
  "0004_user_opportunities.sql": "-- Opportunities the applicant brought themselves.\n--\n-- Research finding (PRODUCT_ARCHITECTURE.md §2.3.1): there is no\n-- machine-readable source of open UK trust and foundation calls, and none is\n-- coming. Find a Grant is ~120 grants and central government only; 360Giving\n-- is awarded grants by design. So the pipeline starts with the applicant\n-- pasting the funder's own guidance.\n--\n-- Such an opportunity must never be dressed up as a verified register entry.\n\nALTER TABLE opportunities\n  ADD COLUMN origin source_type NOT NULL DEFAULT 'funder_published',\n  -- The organisation that pasted it in, NULL for shared register data.\n  -- Deliberately not tenant-scoped by RLS: opportunities are shared reference\n  -- data, and a policy here would need a wider change than this migration.\n  -- Until authentication lands, this column records intent, and the UI is\n  -- what keeps a pasted opportunity attributed to the person who added it.\n  ADD COLUMN added_by_organisation_id text REFERENCES organisations(id) ON DELETE CASCADE,\n  -- The guidance text the opportunity was read from, so every criterion can\n  -- be traced back to the wording that produced it.\n  ADD COLUMN source_text text,\n  ADD COLUMN instruction_like_content text[] NOT NULL DEFAULT '{}';\n\nCREATE INDEX opportunities_origin_idx ON opportunities (origin, added_by_organisation_id);\n\n-- A criterion carries the wording it was drawn from, exactly as a fact does.\n-- Without the span, \"verify this criterion\" asks a person to take the model's\n-- word for it, which is the one thing this product will not do.\nALTER TABLE eligibility_criteria\n  ADD COLUMN source_span text,\n  ADD COLUMN proposed_by source_type NOT NULL DEFAULT 'funder_published',\n  -- Set when a person looks at a proposed criterion and says it is wrong,\n  -- so it is neither used nor offered again.\n  ADD COLUMN rejected_at timestamptz,\n  ADD COLUMN rejected_by text;\n\nALTER TABLE eligibility_criteria\n  ADD CONSTRAINT verification_is_complete\n    CHECK ((verified_by IS NULL) = (verified_at IS NULL)),\n  ADD CONSTRAINT rejection_is_complete\n    CHECK ((rejected_by IS NULL) = (rejected_at IS NULL)),\n  -- A criterion cannot be both verified and rejected.\n  ADD CONSTRAINT not_verified_and_rejected\n    CHECK (verified_at IS NULL OR rejected_at IS NULL);\n\nCREATE INDEX eligibility_criteria_verified_idx\n  ON eligibility_criteria (opportunity_id, verified_at);\n\n-- ---------------------------------------------------------------------------\n-- Row-level security for opportunities a tenant added themselves.\n-- ---------------------------------------------------------------------------\n--\n-- Until now `opportunities` was shared reference data: readable by everyone,\n-- writable by nobody but the platform. Letting an applicant paste in their own\n-- fund breaks that, and doing it with a blanket GRANT would leak one CIC's\n-- research — which funds they are chasing, and the guidance text they pasted —\n-- to every other tenant.\n--\n-- So: register rows (added_by_organisation_id IS NULL) stay readable by all,\n-- and a pasted row is visible only to the organisation that added it.\n--\n-- Two policies rather than one, deliberately. A single ALL policy would let a\n-- tenant's UPDATE match a register row through USING and then fail its WITH\n-- CHECK, raising an error. Splitting reads from writes means a write simply\n-- does not see rows it may not touch, and affects nothing.\n--\n-- ENABLE without FORCE here, unlike the tenant tables. The table owner is the\n-- publisher of register data — migrations, seeding and ingestion all run as\n-- the owner and must be able to write rows that belong to no tenant. On the\n-- tenant tables FORCE is right because nobody should bypass; here the owner\n-- bypassing IS the mechanism by which shared data exists.\n\nALTER TABLE opportunities ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY shared_or_own_read ON opportunities\n  FOR SELECT\n  USING (\n    added_by_organisation_id IS NULL\n    OR added_by_organisation_id = current_setting('app.organisation_id', true)\n  );\n\n-- Writes touch only your own rows, and cannot create one that pretends to be\n-- register data: WITH CHECK requires the tenant id, so NULL is rejected.\nCREATE POLICY own_write ON opportunities\n  FOR ALL\n  USING (added_by_organisation_id = current_setting('app.organisation_id', true))\n  WITH CHECK (added_by_organisation_id = current_setting('app.organisation_id', true));\n\nGRANT INSERT, UPDATE, DELETE ON opportunities TO app_user;\n\n-- Criteria inherit their parent's visibility. A pasted fund's rules are as\n-- private as the fund itself, and a tenant may not verify or reject a\n-- criterion on shared register data — that would change what every other\n-- organisation sees.\n\nALTER TABLE eligibility_criteria ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY shared_or_own_read ON eligibility_criteria\n  FOR SELECT\n  USING (\n    EXISTS (\n      SELECT 1 FROM opportunities o\n      WHERE o.id = opportunity_id\n        AND (\n          o.added_by_organisation_id IS NULL\n          OR o.added_by_organisation_id = current_setting('app.organisation_id', true)\n        )\n    )\n  );\n\nCREATE POLICY own_write ON eligibility_criteria\n  FOR ALL\n  USING (\n    EXISTS (\n      SELECT 1 FROM opportunities o\n      WHERE o.id = opportunity_id\n        AND o.added_by_organisation_id = current_setting('app.organisation_id', true)\n    )\n  )\n  WITH CHECK (\n    EXISTS (\n      SELECT 1 FROM opportunities o\n      WHERE o.id = opportunity_id\n        AND o.added_by_organisation_id = current_setting('app.organisation_id', true)\n    )\n  );\n\nGRANT INSERT, UPDATE, DELETE ON eligibility_criteria TO app_user;\n\n-- Funders remain shared and read-only to tenants: a pasted opportunity reuses\n-- an existing funder where the name matches, and creating a new funder row is\n-- the platform's job. The application layer performs that insert on the admin\n-- path.\n",
  "0005_project_costs.sql": "-- Whether a project is capital or revenue spend.\n--\n-- `capital_revenue` is one of the ten criteria the eligibility engine can\n-- evaluate, and `loadProject` was returning a hard-coded null for it — so a\n-- funder that only funds capital works could never be matched against a\n-- project, and the criterion silently evaluated as unknown for everyone.\n--\n-- 'both' exists because plenty of projects genuinely are, and forcing a choice\n-- would make the applicant guess.\n\nCREATE TYPE project_spend AS ENUM ('capital', 'revenue', 'both');\n\nALTER TABLE projects ADD COLUMN capital_or_revenue project_spend;\n",
  "0006_award_tags.sql": "-- Classification labels on a past award.\n--\n-- 360Giving publishes these as `classifications[].title` — \"Children and young\n-- people\", \"Heritage and the arts\" — and they are the only field that says\n-- what a grant was FOR. `loadAwards` was returning a hard-coded empty array,\n-- so the prospect engine's cause matching could never fire against the\n-- database: every funder would have looked like they fund nothing in\n-- particular.\n--\n-- Same shape of hole as capital_or_revenue in 0005: the domain logic was\n-- capable, the column was missing, and nothing failed loudly.\n\nALTER TABLE funder_awards ADD COLUMN tags text[] NOT NULL DEFAULT '{}';\n\n-- Prospect research asks \"which funders have funded this kind of work\", so the\n-- lookup is by tag across funders rather than within one.\nCREATE INDEX funder_awards_tags_idx ON funder_awards USING gin (tags);\n",
  "0007_auth.sql": "-- Accounts and sessions.\n--\n-- Everything in this file is ADMIN scope, and that is the whole point.\n--\n-- A session is read BEFORE the tenant is known — reading it is what\n-- ESTABLISHES the tenant — so it cannot itself be protected by a policy that\n-- depends on the tenant already being set. The same goes for the password\n-- hash, which is checked before anyone is anybody. Both therefore follow the\n-- operator-credentials rule from 0002: revoked from PUBLIC, never granted to\n-- app_user, reached only through withAdmin.\n--\n-- This is also why the password hash does NOT live on `users`. 0001 ends with\n-- `GRANT SELECT ON users TO app_user`, and that table carries no policy, so\n-- any tenant connection can read every row of it. A hash column added there\n-- would be readable by every signed-in customer of the platform.\n\nCREATE TABLE user_passwords (\n  user_id       text PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,\n  password_hash text NOT NULL,\n  updated_at    timestamptz NOT NULL DEFAULT now()\n);\n\nREVOKE ALL ON user_passwords FROM PUBLIC;\n\n-- `id` is the SHA-256 of the session token, never the token itself. The token\n-- exists only in the holder's cookie, so a copy of this table does not let\n-- anyone sign in as anybody: there is nothing here to replay.\nCREATE TABLE sessions (\n  id           text PRIMARY KEY,\n  user_id      text NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  created_at   timestamptz NOT NULL DEFAULT now(),\n  last_seen_at timestamptz NOT NULL DEFAULT now(),\n  expires_at   timestamptz NOT NULL\n);\n\nCREATE INDEX sessions_user_id ON sessions (user_id);\n-- Expiry is swept in bulk, so it wants its own index.\nCREATE INDEX sessions_expires_at ON sessions (expires_at);\n\nREVOKE ALL ON sessions FROM PUBLIC;\n\n-- Sign-in normalises the address before it looks anyone up, so two accounts\n-- differing only in case would make one of them unreachable — and which one\n-- would depend on row order. The existing UNIQUE (email) does not prevent it.\nCREATE UNIQUE INDEX users_email_lower ON users (lower(email));\n\n-- The session records which organisation it is acting as.\n--\n-- This is what keeps the per-request lookup to ONE query against a table the\n-- tenant role cannot see. The alternative — resolving the organisation from\n-- memberships on every request — would need a tenant context in order to read\n-- the very row that establishes the tenant context.\n--\n-- Nullable because a brand-new account has no organisation until onboarding\n-- creates one. A session with no organisation can reach onboarding and nothing\n-- else.\n--\n-- Because the organisation is captured here rather than re-derived, removing\n-- someone from an organisation must also delete their sessions for it.\n-- Revocation is an event, not something re-checked on every request.\nALTER TABLE sessions\n  ADD COLUMN organisation_id text REFERENCES organisations(id) ON DELETE CASCADE;\n\nCREATE INDEX sessions_organisation_id ON sessions (organisation_id);\n\n-- Reading your OWN memberships cannot require already knowing which\n-- organisation you are in — that is precisely what the read is for. So\n-- memberships gains a second way in, keyed on the user rather than the tenant.\n--\n-- Postgres ORs permissive policies together, so this widens SELECT only, and\n-- only to rows that are already yours. Writes stay on the tenant policy alone.\n-- Set app.user_id the same transaction-local way as app.organisation_id, so it\n-- cannot outlive the request that set it.\nCREATE POLICY own_memberships ON memberships\n  FOR SELECT\n  USING (user_id = current_setting('app.user_id', true));\n",
  "0008_auth_throttle.sql": "-- Failed sign-in attempts.\n--\n-- ADMIN scope, for the same reason sessions are: this is read before anybody\n-- is anybody, and it is part of deciding whether they get to be. Revoked from\n-- PUBLIC, never granted to app_user.\n--\n-- `id` is a hash of the thing being limited, prefixed by which axis it is, so\n-- the table is not a plaintext list of who has been trying to sign in and from\n-- where. That is a meaningful improvement over storing addresses in the clear\n-- rather than a strong one — an email address is a small enough space to\n-- brute-force from a hash — but this table holds nothing an attacker could not\n-- work out anyway, and it costs nothing to not keep the list.\nCREATE TABLE auth_attempts (\n  id                text PRIMARY KEY,\n  attempts          integer NOT NULL DEFAULT 0,\n  window_started_at timestamptz NOT NULL DEFAULT now()\n);\n\n-- Lapsed rows are swept in bulk.\nCREATE INDEX auth_attempts_window ON auth_attempts (window_started_at);\n\nREVOKE ALL ON auth_attempts FROM PUBLIC;\n",
};
